export function accountStrings(text) {
    const s = (key) => text(`kit.account.${key}`);
    return {
        close: s('close'), back: s('back'), dialog: s('dialog'), guest: s('guest'),
        guestText: s('guest.text'), signIn: s('guest.signIn'),
        guestB: [s('guest.progress'), s('guest.nickname'), s('guest.friends')],
        games: s('games'), currency: s('currency'), currencyText: s('currency.text'),
        gamesEmptyTitle: s('games.emptyTitle'), gamesEmptyText: s('games.emptyText'),
        settings: s('settings'), soon: s('soon'), friends: s('friends'), avatar: s('avatar'),
        gidLabel: (game) => text('kit.account.gid', { game }), copy: s('copy'), copied: s('copied'),
        openAria: (game, store) => text('kit.account.games.openAria', { game, store }),
        more: s('games.more'), loadingMore: s('games.loading'), hasProfile: s('games.hasProfile'),
        noProfiles: s('games.onlyCurrent'), gamesError: s('games.error'), gamesErrorText: s('error.text'),
        retry: s('retry'), account: s('account'), nick: s('nick'), change: s('change'),
        signInWith: s('signInWith'), privacy: s('privacy'), online: s('privacy.online'),
        requests: s('privacy.requests'), switchAccount: s('switch'), logout: s('logout'),
        nickCurrent: s('nick.current'), nickNew: s('nick.new'), nickRandom: s('nick.random'),
        nickRules: s('nick.rules'), nickHint: s('nick.hint'), nickWarn: s('nick.warn'),
        nickChecking: s('nick.checking'), nickFree: s('nick.free'), nickSave: s('nick.save'),
        nickSaving: s('nick.saving'), nickTaken: (nickname) => text('kit.account.nick.taken', { nickname }),
        nickDone: s('nick.done'), nickDoneText: (nickname) => text('kit.account.nick.doneText', { nickname }),
        done: s('done'), nickLimit: s('nick.limit'), nickLimitText: s('nick.limitText'),
        logoutTitle: s('logout.title'), logoutText: s('logout.text'), logoutConfirm: s('logout.confirm'),
        stay: s('logout.stay'), loading: s('loading'), privacyPolicy: s('privacyPolicy'), terms: s('terms'),
        store: { android: s('store.android'), ios: s('store.ios'), web: s('store.web') },
        tabProfile: s('tab.profile'), tabs: s('tabs'), rewards: s('rewards'),
        rewardsSub: (game) => text('kit.account.rewards.text', { game }),
        methods: s('methods'), linked: s('methods.linked'), notLinked: s('methods.notLinked'),
        link: s('methods.link'), unlink: s('methods.unlink'), methodsError: s('methods.error'),
        logoutAll: s('logoutAll'), playingNow: s('games.playing'), otherGames: s('games.other'),
        play: s('games.play'), install: s('games.install'), now: s('games.now'), gamesNote: s('games.note'), earnedWord: s('games.earned'), earnedWordCap: s('games.earned.cap'),
        deleteAccount: s('delete'),
        earned: (game) => text('kit.account.earned', { game }), settingsOpen: s('settings.open'),
        idLabel: s('id'), accountError: s('error'),
    };
}
